B=[
('بَنُو غَسَّانَ','Gassânoğulları',[
('كَانَ بَنُو غَسَّانَ قَبِيلَةً عَرَبِيَّةً تَسْكُنُ الشَّامَ، وَتَحْكُمُ تَحْتَ سُلْطَانِ الرُّومِ.','Gassânoğulları Şam’da yaşayan ve Rum hâkimiyeti altında yöneten bir Arap kabilesiydi.'),
('وَكَانُوا نَصَارَى، أَهْلَ كَرَمٍ وَشِعْرٍ وَفُرُوسِيَّةٍ.','Hıristiyandılar; cömertlik, şiir ve binicilik ehliydiler.'),
('وَكَانَ لِأَمِيرِهِمْ بِنْتٌ جَمِيلَةٌ اسْمُهَا هِنْدٌ.','Emirlerinin Hind adında güzel bir kızı vardı.'),
('وَفِي تِلْكَ الْأَيَّامِ ظَهَرَ فِي مَكَّةَ نَبِيٌّ يَدْعُو إِلَى عِبَادَةِ اللَّهِ وَحْدَهُ.','O günlerde Mekke’de yalnız Allah’a ibadete çağıran bir peygamber zuhur etti.'),
('فَتَحَدَّثَ النَّاسُ فِي الشَّامِ عَنْ هَذَا الدِّينِ الْجَدِيدِ.','Şam’da insanlar bu yeni dinden söz etti.'),
('وَكَانَ بَعْضُهُمْ يَخَافُهُ، وَبَعْضُهُمْ يَشْتَاقُ إِلَى مَعْرِفَتِهِ.','Bazıları ondan korkuyor, bazıları onu tanımayı arzuluyordu.')]),
('الْفَارِسُ','Süvari',[
('وَكَانَ فِي الْحِيرَةِ فَتًى شُجَاعٌ اسْمُهُ حَمَّادٌ، يُحِبُّ الشِّعْرَ وَالْخَيْلَ.','Hîre’de şiiri ve atları seven Hammâd adında cesur bir genç vardı.'),
('فَرَأَى هِنْدًا فِي سُوقٍ مِنْ أَسْوَاقِ الشَّامِ، فَأَحَبَّهَا.','Hind’i Şam çarşılarından birinde gördü ve onu sevdi.'),
('وَلَكِنَّ أَبَاهَا كَانَ قَدْ وَعَدَ بِهَا أَمِيرًا رُومِيًّا.','Ama babası onu Rum bir emire söz vermişti.'),
('فَقَالَتْ هِنْدٌ: «لَا أَتَزَوَّجُ إِلَّا مَنْ يَخْتَارُهُ قَلْبِي.»','Hind dedi ki: “Ancak kalbimin seçtiğiyle evlenirim.”'),
('فَأَصْبَحَ حُبُّهُمَا سِرًّا يَخَافَانِ أَنْ يَنْكَشِفَ.','Aşkları açığa çıkmasından korktukları bir sır oldu.')]),
('الْيَرْمُوكُ','Yermük',[
('ثُمَّ جَاءَتْ جُيُوشُ الْمُسْلِمِينَ إِلَى الشَّامِ فِي خِلَافَةِ أَبِي بَكْرٍ وَعُمَرَ.','Sonra Ebû Bekir ve Ömer’in hilafetinde Müslüman orduları Şam’a geldi.'),
('وَجَمَعَ هِرَقْلُ مَلِكُ الرُّومِ جَيْشًا عَظِيمًا، وَكَانَ مَعَهُ بَنُو غَسَّانَ.','Rum kralı Herakleios büyük bir ordu topladı; Gassânoğulları da onunla birlikteydi.'),
('فَالْتَقَى الْجَيْشَانِ عِنْدَ نَهْرِ الْيَرْمُوكِ، وَقَائِدُ الْمُسْلِمِينَ خَالِدُ بْنُ الْوَلِيدِ.','İki ordu Yermük ırmağında karşılaştı; Müslümanların komutanı Hâlid b. Velîd idi.'),
('وَدَامَتِ الْمَعْرَكَةُ أَيَّامًا، ثُمَّ انْهَزَمَ الرُّومُ هَزِيمَةً كَبِيرَةً.','Savaş günlerce sürdü, sonra Rumlar büyük bir yenilgiye uğradı.'),
('فَقَالَ هِرَقْلُ وَهُوَ يُغَادِرُ الشَّامَ: «سَلَامٌ عَلَيْكِ يَا سُورِيَةُ، سَلَامًا لَا لِقَاءَ بَعْدَهُ.»','Herakleios Şam’dan ayrılırken dedi ki: “Elveda ey Suriye, ardından buluşma olmayan bir elveda.”')]),
('الِاخْتِيَارُ','Seçim',[
('وَرَأَى حَمَّادٌ عَدْلَ الْمُسْلِمِينَ وَوَفَاءَهُمْ بِالْعُهُودِ.','Hammâd Müslümanların adaletini ve ahitlerine vefasını gördü.'),
('فَأَسْلَمَ، وَقَالَ: «هَذَا دِينٌ يَجْعَلُ الضَّعِيفَ قَوِيًّا وَالْعَبْدَ حُرًّا.»','Müslüman oldu ve dedi ki: “Bu, zayıfı güçlü, köleyi hür kılan bir dindir.”'),
('وَأَمَّا أَبُو هِنْدٍ فَهَرَبَ مَعَ الرُّومِ، ثُمَّ رَجَعَ فَصَالَحَ الْمُسْلِمِينَ.','Hind’in babası Rumlarla kaçtı, sonra dönüp Müslümanlarla barış yaptı.'),
('فَتَرَكُوا لَهُ أَرْضَهُ وَكَنِيسَتَهُ، وَأَخَذُوا مِنْهُ جِزْيَةً قَلِيلَةً.','Ona toprağını ve kilisesini bıraktılar ve ondan az bir cizye aldılar.'),
('وَتَزَوَّجَ حَمَّادٌ هِنْدًا بَعْدَ أَنْ رَضِيَ أَبُوهَا.','Babası razı olduktan sonra Hammâd Hind ile evlendi.'),
('وَيَرْوِي زَيْدَانُ كَيْفَ دَخَلَ الْإِسْلَامُ الشَّامَ بِالسَّيْفِ وَبِالْعَدْلِ مَعًا، وَكَيْفَ تَغَيَّرَتْ حَيَاةُ الْعَرَبِ هُنَاكَ.','Zeydân, İslâm’ın Şam’a kılıçla ve adaletle birlikte nasıl girdiğini ve oradaki Arapların hayatının nasıl değiştiğini anlatır.')]),
]
